package com.example.app08.application.service; import com.example.app08.domain.entity.Ticket; import com.example.app08.infrastructure.repository.TicketRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class TicketService { private final TicketRepository repository; public TicketService(TicketRepository repository) { this.repository=repository; } @Transactional(readOnly=true) public List<Ticket> list() { return repository.findAll(); } @Transactional public Ticket create(Ticket e) { return repository.save(e); } }
